/**
 * Fail-safe planning at the single-flight boundary: a planner failure must stay with the thread that caused it. A
 * waiter parked on a failed flight replans instead of inheriting the owner's exception, a wait is bounded by the
 * planning deadline, and algebra the packed codec cannot encode is rejected before any search or cost-model work.
 */
class PackedPlanningFailSafeTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void failedOwnerFlightMakesWaiterReplanInsteadOfInheritingTheFailure() {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 11L);
		TupleExpr query = new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c"));
		PackedPlanCache.Fingerprint fingerprint = cache.fingerprint(query);
		PackedPlanCache.FlightClaim owner = cache.beginFlight(fingerprint, context, query);
		PackedPlanCache.FlightClaim waiter = cache.beginFlight(fingerprint, context, query);
		assertTrue(owner.owner());
		assertFalse(waiter.owner());

		cache.fail(owner, new PackedMemoInvariantException("memo invariant breached during planning"));

		assertNull(waiter.await(), "a waiter must observe a failed flight as 'plan yourself', not as an exception");
		PackedPlanCache.FlightClaim replan = cache.beginFlight(fingerprint, context, query);
		assertTrue(replan.owner(), "the failed flight was removed, so the waiter becomes the new owner");
		cache.fail(replan, new IllegalStateException("release test flight"));
	}

	@Test
	void waiterReplansAndSucceedsWhenTheOwnerFails() throws Exception {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 11L);
		TupleExpr query = new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c"));
		CountDownLatch ownerInSession = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		AtomicReference<Thread> ownerThread = new AtomicReference<>();
		AtomicInteger sessions = new AtomicInteger();
		FailingOwnerCostModel model = new FailingOwnerCostModel(ownerThread, ownerInSession, releaseOwner, sessions,
				1);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<PackedPlanningResult> owner = executor.submit(() -> {
				ownerThread.set(Thread.currentThread());
				return PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(), cache, context, model);
			});
			assertTrue(ownerInSession.await(30, TimeUnit.SECONDS), "owner never opened its cost session");
			AtomicReference<Thread> waiterThread = new AtomicReference<>();
			Future<PackedPlanningResult> waiter = executor.submit(() -> {
				waiterThread.set(Thread.currentThread());
				return PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(), cache, context, model);
			});
			assertTrue(awaitParked(List.of(waiterThread)), "waiter never parked on the owner's flight");
			releaseOwner.countDown();

			ExecutionException ownerFailure = assertThrows(ExecutionException.class,
					() -> owner.get(30, TimeUnit.SECONDS));
			assertInstanceOf(IllegalArgumentException.class, ownerFailure.getCause(),
					"the owner keeps its own typed failure");
			PackedPlanningResult replanned = waiter.get(30, TimeUnit.SECONDS);
			assertNotNull(replanned.selectedPlan(), "the waiter must plan for itself after the owner failed");
			assertFalse(replanned.metrics().planCacheHit());
			assertEquals(2, sessions.get(), "owner session (failed) + waiter session (replanned)");
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
		}
	}

	@Test
	void waiterFallsBackToIndependentPlanningWhenTwoOwnersFail() throws Exception {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 11L);
		TupleExpr query = new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c"));
		CountDownLatch ownerInSession = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		AtomicReference<Thread> ownerThread = new AtomicReference<>();
		AtomicInteger sessions = new AtomicInteger();
		// The first two cost sessions fail (the original owner and whichever waiter takes over ownership); the third
		// one, opened by the remaining waiter's independent planning, succeeds.
		FailingOwnerCostModel model = new FailingOwnerCostModel(ownerThread, ownerInSession, releaseOwner, sessions,
				2);
		ExecutorService executor = Executors.newFixedThreadPool(3);
		try {
			Future<PackedPlanningResult> owner = executor.submit(() -> {
				ownerThread.set(Thread.currentThread());
				return PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(), cache, context, model);
			});
			assertTrue(ownerInSession.await(30, TimeUnit.SECONDS), "owner never opened its cost session");
			AtomicReference<Thread> firstWaiterThread = new AtomicReference<>();
			AtomicReference<Thread> secondWaiterThread = new AtomicReference<>();
			Future<PackedPlanningResult> firstWaiter = executor.submit(() -> {
				firstWaiterThread.set(Thread.currentThread());
				return PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(), cache, context, model);
			});
			Future<PackedPlanningResult> secondWaiter = executor.submit(() -> {
				secondWaiterThread.set(Thread.currentThread());
				return PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(), cache, context, model);
			});
			assertTrue(awaitParked(List.of(firstWaiterThread, secondWaiterThread)),
					"both waiters must park on the owner's flight");
			releaseOwner.countDown();

			assertThrows(ExecutionException.class, () -> owner.get(30, TimeUnit.SECONDS));
			List<PackedPlanningResult> planned = new ArrayList<>();
			List<Throwable> failed = new ArrayList<>();
			for (Future<PackedPlanningResult> waiter : List.of(firstWaiter, secondWaiter)) {
				try {
					planned.add(waiter.get(30, TimeUnit.SECONDS));
				} catch (ExecutionException failure) {
					failed.add(failure.getCause());
				}
			}
			assertEquals(1, failed.size(), "exactly one waiter took over ownership and met the second failure");
			assertInstanceOf(IllegalArgumentException.class, failed.get(0));
			assertEquals(1, planned.size(), "the other waiter must fall back to independent planning");
			assertNotNull(planned.get(0).selectedPlan());
			assertEquals(3, sessions.get(), "two failed owner sessions + one independent planning session");
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
		}
	}

	@Test
	void waiterWaitIsBoundedByPlanningDeadline() throws Exception {
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 11L);
		TupleExpr query = new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c"));
		// One shared goal so that owner and waiter carry the same absolute deadline (flights only merge on equal
		// planning limits).
		OptimizationGoal deadlineGoal = OptimizationGoal.root()
				.asBudgeted(Duration.ofMillis(300L),
						Integer.MAX_VALUE);
		CountDownLatch ownerInSession = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		AtomicReference<Thread> ownerThread = new AtomicReference<>();
		AtomicInteger sessions = new AtomicInteger();
		FailingOwnerCostModel model = new FailingOwnerCostModel(ownerThread, ownerInSession, releaseOwner, sessions,
				0);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<PackedPlanningResult> owner = executor.submit(() -> {
				ownerThread.set(Thread.currentThread());
				return PackedCascadesPlanner.optimize(query.clone(), deadlineGoal, cache, context, model);
			});
			assertTrue(ownerInSession.await(30, TimeUnit.SECONDS), "owner never opened its cost session");
			Future<PackedPlanningResult> waiter = executor.submit(
					() -> PackedCascadesPlanner.optimize(query.clone(), deadlineGoal, cache, context, model));

			PackedPlanningResult bounded = waiter.get(10, TimeUnit.SECONDS);
			assertNotNull(bounded.selectedPlan(),
					"a waiter must stop waiting at the planning deadline and plan independently");
			assertFalse(owner.isDone(), "the owner is still blocked; the waiter did not depend on it");
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
		}
	}

	@Test
	void unsupportedOperatorFailsFastBeforeAnyCostSessionOpens() {
		TupleExpr query = new OpaqueTuple(new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c")));
		AtomicInteger sessions = new AtomicInteger();
		PackedCostModel counting = new CountingCostModel(sessions);

		CascadesPlanningException failure = assertThrows(CascadesPlanningException.class,
				() -> PackedCascadesPlanner.optimize(query.clone(), OptimizationGoal.root(), counting));

		assertInstanceOf(UnsupportedCascadesOperatorException.class, failure);
		assertTrue(failure.getMessage().contains(OpaqueTuple.class.getName()),
				"the failure names the unsupported operator: " + failure.getMessage());
		assertEquals(0, sessions.get(), "an unsupported operator must be rejected before search opens a session");
	}

	@Test
	void unsupportedOperatorSurfacesAsCascadesPlanningExceptionThroughTheFacade() {
		TupleExpr query = new OpaqueTuple(new Join(sp("a", "urn:p", "b"), sp("b", "urn:q", "c")));

		RuntimeException failure = assertThrows(RuntimeException.class,
				() -> new CascadesPlanner().optimize(query, OptimizationGoal.root()));

		assertInstanceOf(CascadesPlanningException.class, failure,
				"planning failed with " + failure.getClass().getName() + ", which is not a planning failure type");
	}

	// ---------------------------------------------------------------- helpers

	private static boolean awaitParked(List<AtomicReference<Thread>> threads) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (System.nanoTime() < deadline) {
			boolean allParked = true;
			for (AtomicReference<Thread> reference : threads) {
				Thread thread = reference.get();
				Thread.State state = thread == null ? null : thread.getState();
				if (state != Thread.State.WAITING && state != Thread.State.TIMED_WAITING) {
					allParked = false;
				}
			}
			if (allParked) {
				return true;
			}
			Thread.sleep(5L);
		}
		return false;
	}

	private static StatementPattern sp(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_const_" + predicate.substring(4), VF.createIRI(
				predicate), false, true), Var.of(object));
	}

	/** Blocks the owner thread in its first session, then fails the first {@code failingSessions} sessions. */
	private static final class FailingOwnerCostModel implements PackedCostModel {

		private final AtomicReference<Thread> ownerThread;
		private final CountDownLatch ownerInSession;
		private final CountDownLatch releaseOwner;
		private final AtomicInteger sessions;
		private final int failingSessions;

		private FailingOwnerCostModel(AtomicReference<Thread> ownerThread, CountDownLatch ownerInSession,
				CountDownLatch releaseOwner, AtomicInteger sessions, int failingSessions) {
			this.ownerThread = ownerThread;
			this.ownerInSession = ownerInSession;
			this.releaseOwner = releaseOwner;
			this.sessions = sessions;
			this.failingSessions = failingSessions;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			int session = sessions.incrementAndGet();
			if (Thread.currentThread() == ownerThread.get()) {
				ownerInSession.countDown();
				try {
					if (!releaseOwner.await(30, TimeUnit.SECONDS)) {
						throw new IllegalStateException("owner release timed out");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException(interrupted);
				}
			}
			if (session <= failingSessions) {
				throw new IllegalArgumentException("cost model failure in session " + session);
			}
			return PackedCostModel.super.openSession(query);
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 100.0d : Double.NaN;
		}
	}

	private static final class CountingCostModel implements PackedCostModel {

		private final AtomicInteger sessions;

		private CountingCostModel(AtomicInteger sessions) {
			this.sessions = sessions;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			sessions.incrementAndGet();
			return PackedCostModel.super.openSession(query);
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 100.0d : Double.NaN;
		}
	}

	private static final class OpaqueTuple extends UnaryTupleOperator {

		private static final long serialVersionUID = 1L;

		private OpaqueTuple(TupleExpr argument) {
			super(argument);
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}
	}
}
